import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"UGSo Special","description":"Animated SVG lines and summing nodes for ioBroker VIS 2.","frontmatter":{"title":"UGSo Special","description":"Animated SVG lines and summing nodes for ioBroker VIS 2."},"headers":[],"relativePath":"en/iobroker/widgets/ugso-spezial/index.md","filePath":"en/iobroker/widgets/ugso-spezial/index.md","lastUpdated":1794428176000}'),n={name:"en/iobroker/widgets/ugso-spezial/index.md"};function r(s,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ugso-special" tabindex="-1">UGSo Special <a class="header-anchor" href="#ugso-special" aria-label="Permalink to &quot;UGSo Special&quot;">​</a></h1><p><strong>UGSo Special</strong> visualizes data flows in VIS 2, such as power readings from several devices. The set contains two widgets.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> connects points with straight, right-angle or waypoint routes. Colors, dash lengths and arrowheads are configurable. Positive values animate forward, negative values reverse the direction, and zero stops the animation. Speed can be fixed or proportional to the absolute value.</li><li><strong>SVG LineBox</strong> adds up to four input lines and an optional correction value. It can send the total to up to two output lines or write it in the runtime view to an existing writable numeric state under <code>0_userdata.0</code>. If a selected input is unavailable, the node waits for its value.</li></ul><p>In the editor, drag a yellow endpoint to snap it to another line or LineBox. An endpoint with an arrowhead cannot snap. Snapping aligns the graphics; configure value routing separately in the LineBox.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="catalogue-preparation-0-1-34" tabindex="-1">Catalogue preparation 0.1.34 <a class="header-anchor" href="#catalogue-preparation-0-1-34" aria-label="Permalink to &quot;Catalogue preparation 0.1.34&quot;">​</a></h3><p>This release includes complete release notes in all eleven catalogue languages, corrected package dependencies, automated linting and ioBroker package checks. Releases use GitHub Actions with npm provenance. bluefox is listed as an npm co-owner. Inclusion in the official catalogue remains pending; widget features and existing projects are preserved.</p><p>The package is now named <code>iobroker.vis-2-widgets-ugso-special</code>. Export existing VIS 2 projects as a backup, install the new package and restart VIS 2. Check the projects before removing the previous package. Widget template IDs and the internal federation name are retained.</p><p>A running VIS 2 installation is required. Install the widget set from its GitHub URL in ioBroker Admin (expert mode). Restart VIS 2 after updates to load the new version. Both widgets appear under <strong>UGSo Special</strong> in the editor palette.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">npm</a></li></ul>',11)])])}const h=a(n,[["render",r]]);export{g as __pageData,h as default};
